const a={web3_267:{lianjieqianbao:"Conectar Carteira",wodeqianbaodizhi:"Meu Endereço de Carteira",licai:"Mineração",jinrulicai:"Entrar na Mineração",yishouyi:"Lucros Obtidos",shouyilv:"Taxa de Retorno",zhiyajine:"Valor da Mineração",canyu:"Participar",shouyishijian:"Tempo de Lucro {amount}/{time}",yifafangshouyi:"Lucros Distribuídos",licaishuju:"Dados de Mineração",zongchanliang:"Produção Total",youxiaojiedian:"Nós Válidos",canyuzhe:"Participantes",yonghushouru:"Renda do Usuário",liudongxinglicaishouyi:"Lucros de Mineração de Liquidez",shouyi:"Lucros",licaishuoming:"Explicação de Mineração",weishenmeyaolicai:"Por que minerar?",weishenmeyaolicai_desc:"A mineração é o processo de aumentar os ativos alocando fundos de forma razoável e usando várias ferramentas financeiras. A mineração eficaz pode combater a inflação, aumentar a renda passiva, alcançar a liberdade financeira e atingir a aposentadoria antecipada.",licaifengxian:"Quais são os riscos da mineração?",licaifengxian_desc:"Os riscos da mineração incluem risco de mercado, risco de inflação, risco de liquidez, risco de crédito e risco operacional. Os investidores devem escolher produtos adequados de acordo com sua tolerância ao risco e diversificar ativos para reduzir os riscos.",xinshoruhekaishilicai:"Como os iniciantes podem começar a minerar?",xinshoruhekaishilicai_desc:"Os iniciantes devem primeiro construir um fundo de emergência, entender sua situação financeira, definir metas, aprender conhecimentos básicos de investimento, começar com produtos de baixo risco, expandir gradualmente seu portfólio e continuar aprendendo e ajustando estratégias.",qukuailianlicai_youshi:"Quais são as vantagens da mineração em blockchain?",qukuailianlicai_youshi_desc:"A mineração em blockchain possui vantagens como descentralização, alta transparência, baixos custos de transação, acessibilidade global e execução automática de contratos inteligentes, oferecendo soluções inovadoras para o mercado de mineração tradicional.",liudongxingzhiyashishenme:"O que é mineração de liquidez?",liudongxingzhiyashishenme_desc:"A mineração de liquidez é o processo de bloquear ativos criptográficos em um protocolo DeFi para fornecer liquidez enquanto obtém recompensas. Os mineradores geralmente recebem uma parte das taxas de transação e recompensas em tokens de governança, sendo um método popular de renda passiva.",ruhepinggulicaichanpindefengxian:"Como avaliar os riscos dos produtos de mineração?",ruhepinggulicaichanpindefengxian_desc:"Para avaliar os riscos dos produtos de mineração, deve-se considerar a volatilidade dos lucros, desempenho histórico, liquidez, reputação do emissor, prazo do investimento e condições de mercado, junto com a tolerância pessoal ao risco.",shouyibiao:"Tabela de Lucros",meirishouyi:"Lucros Diários"}};export{a as default};
